/** Bounded clipboard parsing and Source admission; this class never runs or simulates generation. */
public final class NativeRampConfiguration {
 private static final String[] KEYS={"ramp_vertical_layout","MoatMode","ramp_escalator","ramp_start","ramp_end","ramp_start_half","ramp_end_half","ramp_interpolation","ramp_tread_pixels","ramp_speed","ramp_lift","ramp_extend","ramp_direction","ramp_travel","ramp_match_textures"};
 public record Plan(boolean valid,boolean configurationRequested,RampConfigurationPolicy.Admission admission,NativeRampSettings beforeFooter,NativeRampSettings result,boolean channelFooter){}
 private static int number(CompoundTag tag,String key,int fallback){return tag.contains(key,Tag.TAG_INT)?tag.getInt(key):fallback;}private static boolean flag(CompoundTag tag,String key,boolean fallback){return tag.contains(key,Tag.TAG_BYTE)?tag.getBoolean(key):fallback;}
 public static Plan copied(NativeRampSettings current,int horizontalFacing,int scanFace,CompoundTag values,boolean actorPresent,boolean server,boolean usable,boolean connectedCopyAllowed){
  if(current==null||values==null)throw new NullPointerException();if(values.isEmpty()||!com.vandorlabs.neoforge.copifier.NativeCopiedSettingsValidation.valid(values))return new Plan(false,false,null,current,current,false);
  boolean requested=false;for(String key:KEYS)requested|=values.contains(key);if(values.contains("redstone_trigger",Tag.TAG_INT)){int trigger=values.getInt("redstone_trigger");requested|=trigger==1||trigger==2;}requested&=actorPresent;
  RampConfigurationPolicy.Admission admission=null;NativeRampSettings next=current;
  if(requested){int trigger=number(values,"redstone_trigger",current.powerOn()?1:2);var request=new RampConfigurationPolicy.Request(number(values,"ramp_start_half",number(values,"ramp_start",current.startOffset())*2),number(values,"ramp_end_half",number(values,"ramp_end",current.endOffset())*2),number(values,"ramp_tread_pixels",current.treadPixels()),trigger==1,flag(values,"ramp_lift",current.elevator()),Math.abs(number(values,"ramp_direction",current.resolvedDirection(horizontalFacing))%6),number(values,"ramp_travel",current.travelAxis()),flag(values,"ramp_extend",current.extend()),number(values,"ramp_speed",current.speed()),flag(values,"ramp_match_textures",current.matchTextures()),number(values,"ramp_interpolation",current.interpolation()),number(values,"ramp_escalator",current.escalator()),flag(values,"MoatMode",current.moat()),flag(values,"ramp_vertical_layout",current.verticalLayout()));admission=RampConfigurationPolicy.admit(request,scanFace,server,usable,connectedCopyAllowed);if(admission.accepted()){var r=admission.choices;int d=r.direction==3?0:r.direction==4?1:r.direction==2?2:3;next=new NativeRampSettings(r.startHalf,r.endHalf,r.treadPixels,r.powerOn,r.elevator,r.extend,r.speed,r.matchTextures,r.interpolation,r.escalator,r.moat,r.verticalLayout,r.travel,true,d,current.analogDeployment(),current.channels());}}
  boolean footer=values.contains("redstone_channel");NativeRampSettings result=next;if(footer){ChannelList channels=next.channels();if(values.contains("redstone_channel",Tag.TAG_INT_ARRAY))try{channels=ChannelList.of(values.getIntArray("redstone_channel"));}catch(IllegalArgumentException ignored){}else if(values.contains("redstone_channel",Tag.TAG_INT))channels=ChannelList.of(Math.max(0,values.getInt("redstone_channel")));result=withChannels(next,channels);}return new Plan(true,requested,admission,next,result,footer);
 }

 /** Source configured-item callback uses direct NBT getters, then applies channels even after refusal. */
 public static Plan placement(NativeRampSettings current,int scanFace,CompoundTag settings,boolean server,boolean actorPresent,boolean usable){if(current==null)throw new NullPointerException();if(settings==null||!server||!actorPresent)return new Plan(false,false,null,current,current,false);int h=settings.getInt("Direction")&3;int direction=h==0?3:h==1?4:h==2?2:5;var request=new RampConfigurationPolicy.Request(settings.contains("StartOffsetHalfSteps",Tag.TAG_INT)?settings.getInt("StartOffsetHalfSteps"):settings.getInt("StartOffset")*2,settings.contains("EndOffsetHalfSteps",Tag.TAG_INT)?settings.getInt("EndOffsetHalfSteps"):settings.getInt("EndOffset")*2,settings.getInt("TreadPixels"),settings.getBoolean("PowerOn"),settings.getBoolean("Elevator"),direction,settings.getInt("TravelAxis"),settings.getBoolean("ExtendSegments"),settings.getInt("Speed"),!settings.contains("MatchTextures")||settings.getBoolean("MatchTextures"),settings.getInt("RampInterpolation"),settings.getInt("EscalatorMode"),settings.getBoolean("MoatMode"),settings.getBoolean("RampVerticalLayout"));var admission=RampConfigurationPolicy.admit(request,scanFace,true,usable,false);NativeRampSettings before=current;if(admission.accepted()){var r=admission.choices;int d=r.direction==3?0:r.direction==4?1:r.direction==2?2:3;before=new NativeRampSettings(r.startHalf,r.endHalf,r.treadPixels,r.powerOn,r.elevator,r.extend,r.speed,r.matchTextures,r.interpolation,r.escalator,r.moat,r.verticalLayout,r.travel,true,d,current.analogDeployment(),current.channels());}ChannelList channels=ChannelList.of(Math.max(0,settings.getInt("Channel")));if(settings.contains("RedstoneChannels",Tag.TAG_INT_ARRAY))try{channels=ChannelList.of(settings.getIntArray("RedstoneChannels"));}catch(IllegalArgumentException ignored){}return new Plan(true,true,admission,before,withChannels(before,channels),true);}
 static NativeRampSettings withChannels(NativeRampSettings c,ChannelList channels){return new NativeRampSettings(c.startHalf(),c.endHalf(),c.treadPixels(),c.powerOn(),c.elevator(),c.extend(),c.speed(),c.matchTextures(),c.interpolation(),c.escalator(),c.moat(),c.verticalLayout(),c.travelAxis(),c.hasDirection(),c.direction(),c.analogDeployment(),channels);}
 private NativeRampConfiguration(){}
}
